const characters={
  leona:{name:'Leona',actor:'Carolina Dieckmann',description:'Vaidosa, cheia de atitude e dona de uma presença que ocupa qualquer ambiente. Leona tem uma relação muito particular com o luxo: para ela, passar despercebida nunca é uma opção.',style:'Loiro platinado, unhas vermelhas, botas altas e peças marcantes. Um figurino que transforma confiança em imagem.'},
  foguinho:{name:'Foguinho',actor:'Lázaro Ramos',description:'Carisma, improviso e muita vontade de vencer. Ligado ao universo do Saara, Foguinho traz o humor e a energia de quem está sempre tentando encontrar seu lugar ao sol.',style:'Cabelo e bigode descoloridos, cores que se encontram sem pedir licença e combinações cheias de personalidade.'},
  ellen:{name:'Ellen',actor:'Taís Araújo',description:'Ellen adora moda, grifes e tudo o que promete uma vida mais sofisticada. Sua personalidade expansiva combina com o tamanho dos seus sonhos e com sua atenção às vitrines.',style:'Produções ousadas, referências de grife e o prazer de se vestir para ser vista.'},
  'bel-duda':{name:'Bel & Duda',actor:'Mariana Ximenes e Daniel de Oliveira',description:'Ela se dedica ao universo dos perfumes. Ele trabalha como motoboy. Bel e Duda representam o lado romântico de uma história que aproxima pessoas de universos diferentes.',style:'A leveza e os tons suaves de Bel encontram a informalidade do cotidiano de Duda.'}
};
const menu=document.querySelector('.menu-toggle'),nav=document.querySelector('#navigation'),menuScrim=document.querySelector('.menu-scrim'),drawerClose=document.querySelector('.drawer-close');
function setMenu(open){menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Fechar menu':'Abrir menu');nav.classList.toggle('open',open);menuScrim.hidden=!open;document.body.classList.toggle('menu-open',open);if(open)drawerClose.focus()}
menu.addEventListener('click',()=>setMenu(menu.getAttribute('aria-expanded')!=='true'));
drawerClose.addEventListener('click',()=>{setMenu(false);menu.focus()});menuScrim.addEventListener('click',()=>setMenu(false));
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&nav.classList.contains('open')){setMenu(false);menu.focus()}});
nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>setMenu(false)));
document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button))});document.querySelectorAll('.character-card').forEach(card=>card.hidden=button.dataset.filter!=='all'&&card.dataset.world!==button.dataset.filter)}));
function openDialog(dialog){dialog.showModal();document.body.classList.add('modal-open')}
document.querySelectorAll('.character-card').forEach(card=>card.addEventListener('click',()=>{const key=card.dataset.character,c=characters[key];document.querySelector('#dialog-name').textContent=c.name;document.querySelector('#dialog-actor').textContent=c.actor;document.querySelector('#dialog-description').textContent=c.description;document.querySelector('#dialog-style').textContent=c.style;document.querySelector('#dialog-image').src=`assets/${key}.jpg`;document.querySelector('#dialog-image').alt=`${c.actor} como ${c.name}`;openDialog(document.querySelector('#character-dialog'))}));
document.querySelector('#credits-open').addEventListener('click',()=>openDialog(document.querySelector('#credits-dialog')));
document.querySelectorAll('dialog').forEach(dialog=>{dialog.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>document.body.classList.remove('modal-open'));dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close()}})});
const scenes={luxus:{number:'I.',eyebrow:'O TEMPLO DO CONSUMO',name:'Luxus',description:'Colunas monumentais, vitrines exuberantes e um céu de fantasia. A loja de departamentos de Omar Pasquim faz do exagero uma forma de arte.',details:['ARQUITETURA CLÁSSICA','MODA & DESEJO','LUXO TEATRAL'],image:'luxus.jpg',alt:'Cenário da sofisticada loja de departamentos Luxus'},saara:{number:'II.',eyebrow:'A VIDA ACONTECE NA RUA',name:'Saara',description:'Fachadas coloridas, mercadorias por toda parte e gente que tem história para contar. O comércio popular do Centro do Rio é um mundo de encontros, movimento e bom humor.',details:['CORES & LETREIROS','COMÉRCIO POPULAR','ENERGIA CARIOCA'],image:'saara.jpg',alt:'Foguinho e Omar no comércio popular do Saara'}};
document.querySelectorAll('button[data-scene]').forEach(button=>button.addEventListener('click',()=>{const key=button.dataset.scene,s=scenes[key];document.querySelectorAll('button[data-scene]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button))});document.querySelector('.world-stage').dataset.scene=key;for(const field of ['number','eyebrow','name','description'])document.querySelector(`#world-${field}`).textContent=s[field];const img=document.querySelector('#world-image');img.src=`assets/${s.image}`;img.alt=s.alt;document.querySelector('#world-details').replaceChildren(...s.details.map(detail=>{const span=document.createElement('span');span.textContent=detail;return span}))}));
const quizQuestions=[
  {question:'Seu look ideal para chegar chamando atenção?',luxus:['Elegância impecável','Peças marcantes e cada detalhe no lugar.'],saara:['Mistura com personalidade','Cor, improviso e confiança para sustentar.']},
  {question:'O passeio perfeito em uma tarde no Rio?',luxus:['Vitrines e novidades','Um roteiro cheio de beleza, moda e descobertas.'],saara:['Ruas cheias de histórias','Movimento, conversa e aquela descoberta inesperada.']},
  {question:'Quando aparece uma grande oportunidade, você…',luxus:['Planeja cada movimento','Observa o cenário e entra para fazer bonito.'],saara:['Vai com coragem','Confia no jogo de cintura e faz acontecer.']}
];
let quizStep=0,quizScore={luxus:0,saara:0};
const quizQuestion=document.querySelector('#quiz-question'),quizOptions=document.querySelector('#quiz-options'),quizResult=document.querySelector('#quiz-result');
function renderQuiz(){const q=quizQuestions[quizStep];document.querySelector('#quiz-current').textContent=quizStep+1;quizQuestion.textContent=q.question;quizOptions.querySelector('[data-answer="luxus"] b').textContent=q.luxus[0];quizOptions.querySelector('[data-answer="luxus"] small').textContent=q.luxus[1];quizOptions.querySelector('[data-answer="saara"] b').textContent=q.saara[0];quizOptions.querySelector('[data-answer="saara"] small').textContent=q.saara[1];document.querySelectorAll('.progress-dots i').forEach((dot,index)=>dot.classList.toggle('active',index<=quizStep))}
quizOptions.querySelectorAll('button').forEach(button=>button.addEventListener('click',()=>{quizScore[button.dataset.answer]++;if(quizStep<quizQuestions.length-1){quizStep++;renderQuiz();return}const side=quizScore.luxus>quizScore.saara?'luxus':'saara';quizQuestion.hidden=true;quizOptions.hidden=true;document.querySelector('.quiz-progress').hidden=true;quizResult.hidden=false;document.querySelector('#result-symbol').textContent=side==='luxus'?'✦':'✳';document.querySelector('#result-title').textContent=side==='luxus'?'Sua energia é Luxus.':'Sua energia é Saara.';document.querySelector('#result-copy').textContent=side==='luxus'?'Você gosta de presença, beleza e de transformar cada chegada em acontecimento. Seu brilho pede uma vitrine à altura.':'Você tem espontaneidade, calor humano e jogo de cintura. Seu brilho aparece no movimento e nos encontros.'}));
document.querySelector('#quiz-restart').addEventListener('click',()=>{quizStep=0;quizScore={luxus:0,saara:0};quizQuestion.hidden=false;quizOptions.hidden=false;document.querySelector('.quiz-progress').hidden=false;quizResult.hidden=true;renderQuiz()});
let installPrompt;
const installButton=document.querySelector('#install-app'),iosTip=document.querySelector('#ios-tip');
window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();installPrompt=event;installButton.hidden=false});
installButton.addEventListener('click',async()=>{if(!installPrompt)return;installPrompt.prompt();await installPrompt.userChoice;installPrompt=null;installButton.hidden=true});
if(/iphone|ipad|ipod/i.test(navigator.userAgent)&&!window.matchMedia('(display-mode: standalone)').matches)iosTip.hidden=false;
if('serviceWorker' in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('/sw.js').catch(()=>{}));
const progressBar=document.querySelector('.reading-progress span');let progressTick=false;
function updateReadingProgress(){const max=document.documentElement.scrollHeight-innerHeight;const value=max>0?Math.min(scrollY/max,1):0;progressBar.style.transform=`scaleX(${value})`;progressTick=false}
addEventListener('scroll',()=>{if(!progressTick){progressTick=true;requestAnimationFrame(updateReadingProgress)}},{passive:true});updateReadingProgress();
const sectionLinks=[...nav.querySelectorAll('a[href^="#"]')],observedSections=sectionLinks.map(link=>document.querySelector(link.getAttribute('href'))).filter(Boolean);
if('IntersectionObserver' in window){
  const sectionObserver=new IntersectionObserver(entries=>{const visible=entries.filter(entry=>entry.isIntersecting).sort((a,b)=>b.intersectionRatio-a.intersectionRatio)[0];if(!visible)return;sectionLinks.forEach(link=>{const active=link.getAttribute('href')===`#${visible.target.id}`;if(active)link.setAttribute('aria-current','true');else link.removeAttribute('aria-current')})},{rootMargin:'-28% 0px -55%',threshold:[0,.2,.5]});
  observedSections.forEach(section=>sectionObserver.observe(section));
  const revealTargets=document.querySelectorAll('.intro>*,.section-heading>*,.character-card,.worlds-top,.world-stage,.vibe-heading,.quiz-card,.record-art,.soundtrack-copy,.install-strip,.endnote');
  document.body.classList.add('reveal-ready');revealTargets.forEach(target=>target.classList.add('reveal-item'));
  const revealObserver=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-visible');revealObserver.unobserve(entry.target)}}),{rootMargin:'0px 0px -8%',threshold:.08});
  revealTargets.forEach(target=>revealObserver.observe(target));
}
